import sys, os, json
sys.path.insert(0, '/data/scripts')
import flowsint_client as fc
import tech_enricher
from poc_client import PoCClient

# ── request scope ─────────────────────────────────────────────────────────────
# Two triggers reach this node: the weekly schedule (no body at all) and the
# Tech Intel tab's "Enrich" button (POST /webhook/tech-enrich with a sketch_id).
_sb = _items[0].get('json', {}) if _items else {}
_sb = _sb.get('body', _sb) if isinstance(_sb.get('body'), dict) else _sb
if not isinstance(_sb, dict):
    _sb = {}

# A schedule trigger carries no sketch_id. Falling back to FLOWSINT_SKETCH_ID
# pointed the whole pass at the throwaway default sketch that no campaign reads --
# and enriching an empty sketch succeeds, so it failed silently. resolve_campaign_sketch
# picks the most recent campaign from the shared registry instead.
sketch_id = fc.resolve_campaign_sketch(str(_sb.get('sketch_id') or ''))

result = {'ok': True, 'sketch_id': sketch_id, 'steps': {}}

# ── bounds ────────────────────────────────────────────────────────────────────
# Configuration panel override > .env > built-in, resolved against ONE registry
# read. Note resolve_int's second parameter is `_stored`, not a default value --
# passing a number there makes the panel override silently inert.
LIMIT, CVES = 500, 10
try:
    import spotter_settings as _st
    _cfg = _st.resolve_many([
        'TECH_ENRICH_MAX_NODES', 'CVE_MAX_PER_TECH',
        'POC_MAX_PER_CVE', 'POC_MIN_STARS', 'POC_MIRROR_MAX_AGE_DAYS',
    ])
    LIMIT = _cfg.get('TECH_ENRICH_MAX_NODES') or LIMIT
    CVES  = _cfg.get('CVE_MAX_PER_TECH') or CVES
    # poc_client reads its own caps from the environment so it stays usable
    # standalone from the host. Publishing the resolved values here is what lets
    # a Configuration-panel override actually reach it inside this run.
    for _k in ('POC_MAX_PER_CVE', 'POC_MIN_STARS', 'POC_MIRROR_MAX_AGE_DAYS'):
        if _cfg.get(_k) is not None:
            os.environ[_k] = str(_cfg[_k])
except Exception as e:
    result['steps']['settings'] = {'error': str(e), 'using': 'built-in defaults'}
try:
    if _sb.get('limit'):
        LIMIT = max(1, min(5000, int(_sb['limit'])))
except (TypeError, ValueError):
    pass

# ── PoC mirror state ──────────────────────────────────────────────────────────
# Reported FIRST and unconditionally. A mirror that was never synced, or is
# months old, answers "no public exploit" for every recent CVE -- which is
# indistinguishable from a real negative unless the age is on the record.
try:
    _poc = PoCClient()
    result['steps']['poc_mirror'] = _poc.mirror_status()
except Exception as e:
    result['steps']['poc_mirror'] = {'error': str(e), 'available': False}

# ── 1. enrich Technology/Service nodes ────────────────────────────────────────
# This is the step that makes the Tech Intel tab's Vulnerable Technology panel
# populate: it writes cve_count / poc_count / exploit_available / composite_risk
# back onto each node, under nodeProperties.* where every reader looks.
cve_ids, techs = [], []
try:
    _enr = tech_enricher.enrich_technology_nodes(
        sketch_id=sketch_id, limit=LIMIT, cves_per_tech=CVES)
    cve_ids = _enr.get('cve_ids') or []
    techs   = _enr.get('technologies') or []
    result['steps']['enrich'] = {
        k: v for k, v in _enr.items()
        if k not in ('poc_mirror', 'cve_ids', 'technologies')
    }
    if _enr.get('errors'):
        result['ok'] = False
except Exception as e:
    result['ok'] = False
    result['steps']['enrich'] = {'error': str(e)}

# ── 2. refresh the MITRE ATT&CK bundle ────────────────────────────────────────
try:
    from mitre_client import MITREClient
    MITREClient().refresh()
    result['steps']['mitre'] = {'refreshed': True}
except Exception as e:
    result['steps']['mitre'] = {'error': str(e)}

# ── 3. rebuild the RAG collections ────────────────────────────────────────────
# CVEs are indexed BY ID from the enrichment pass rather than by re-running a
# keyword search: those are the CVEs that actually matched an asset, and every
# lookup is a cache hit because step 1 just performed it.
try:
    from rag_indexer import RAGIndexer
    _ix = RAGIndexer()
    _counts = {}
    _counts['mitre']  = _ix.index_mitre()
    _counts['guides'] = _ix.index_guides({
        'KeePass memory dump': 'Dump KeePass master password from memory during active session using KeeThief or KeeDump.',
        'SAP GUI credential store': 'Extract SAPUILandscape.xml and saved connection entries from %APPDATA%\\SAP\\Common.',
        'Citrix ICA file theft': 'Steal .ica files from Downloads/temp and extract saved credentials from Credential Manager.',
        'Mainframe TN3270 session hijack': 'Capture TN3270 traffic on TCP/23 or inject into terminal emulator process.',
        'AS/400 TN5250 credential theft': 'Steal TN5250 connection profiles and keylog AS/400 signon credentials.',
        'PAM vault pivot': 'Use extracted PAM user credentials to access the vault or transparent-auth to managed systems.',
    })
    _counts['cves'] = _ix.index_cve_ids(cve_ids) if cve_ids else 0
    _counts['pocs'] = _ix.index_pocs(cve_ids) if cve_ids else 0
    if techs:
        _counts['asset_inventory'] = _ix.index_asset_inventory(techs)
    result['steps']['rag'] = _counts
except Exception as e:
    result['ok'] = False
    result['steps']['rag'] = {'error': str(e)}

# ── summary line ───────────────────────────────────────────
_e = result['steps'].get('enrich', {})
_m = result['steps'].get('poc_mirror', {})
result['summary'] = (
    "%s of %s technology nodes enriched; %s with CVEs, %s with public exploit code"
    % (_e.get('nodes_enriched', 0), _e.get('nodes_seen', 0),
       _e.get('nodes_with_cves', 0), _e.get('nodes_with_exploits', 0))
)
if _m.get('stale'):
    result['summary'] += (
        " | WARNING: PoC mirror is stale (age %s d) -- run scripts/sync_poc_mirror.py; "
        "absence of exploit code is not evidence none exists" % _m.get('age_days')
    )

return [{'json': result}]
